"""Invoices from the billing system's export, with their money in whole cents so nothing rounds twice."""
import json
from dataclasses import dataclass
from datetime import date
from pathlib import Path


@dataclass(frozen=True)
class Line:
    description: str
    quantity: int
    unit_cents: int

    @property
    def cents(self):
        return self.quantity * self.unit_cents


@dataclass(frozen=True)
class Invoice:
    id: str
    account_id: str
    issued: date
    lines: tuple
    tax_rate_bp: int  # basis points, so 825 means 8.25%

    @property
    def subtotal_cents(self):
        return sum(line.cents for line in self.lines)

    @property
    def tax_cents(self):
        """Tax on the whole invoice, rounded half up to the cent."""
        return (self.subtotal_cents * self.tax_rate_bp + 5000) // 10000

    @property
    def total_cents(self):
        return self.subtotal_cents + self.tax_cents


def load_invoices(path):
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    return [
        Invoice(
            id=item["id"],
            account_id=item["account_id"],
            issued=date.fromisoformat(item["issued"]),
            lines=tuple(Line(ln["description"], ln["quantity"], ln["unit_cents"]) for ln in item["lines"]),
            tax_rate_bp=item["tax_rate_bp"],
        )
        for item in data["invoices"]
    ]

import unittest
from pathlib import Path

from billing.invoices import load_invoices
from billing.report import monthly_report

DATA = Path(__file__).resolve().parent.parent.joinpath("data", "invoices.json")


class MonthlyReport(unittest.TestCase):
    def setUp(self):
        self.rows = monthly_report(load_invoices(DATA))

    def test_one_row_per_account_and_month(self):
        self.assertEqual(len(self.rows), 8)

    def test_sorted_by_account_then_month(self):
        keys = [(r["account_id"], r["month"]) for r in self.rows]
        self.assertEqual(keys, sorted(keys))
        self.assertEqual(keys[:2], [("ACCT-1001", "2026-09"), ("ACCT-1001", "2026-10")])

    def test_counts_the_invoices(self):
        self.assertEqual(self.rows[0]["invoices"], 2)

    def test_sums_the_money(self):
        first = self.rows[0]
        self.assertEqual((first["subtotal_cents"], first["tax_cents"], first["total_cents"]), (57550, 4748, 62298))

    def test_months_read_year_then_month(self):
        self.assertEqual({r["month"] for r in self.rows}, {"2026-09", "2026-10"})

    def test_no_invoices_no_rows(self):
        self.assertEqual(monthly_report([]), [])


if __name__ == "__main__":
    unittest.main()

import unittest
from datetime import date
from pathlib import Path

from billing.invoices import Invoice, Line, load_invoices

DATA = Path(__file__).resolve().parent.parent.joinpath("data", "invoices.json")


class Invoices(unittest.TestCase):
    def setUp(self):
        self.invoices = load_invoices(DATA)

    def test_loads_every_invoice(self):
        self.assertEqual(len(self.invoices), 11)

    def test_a_line_is_quantity_times_unit(self):
        self.assertEqual(Line("Storage overage (GB)", 3, 1250).cents, 3750)

    def test_subtotal(self):
        self.assertEqual(self.invoices[0].subtotal_cents, 38550)

    def test_total_adds_the_tax(self):
        self.assertEqual(self.invoices[0].tax_cents, 3180)
        self.assertEqual(self.invoices[0].total_cents, 41730)

    def test_tax_rounds_half_up(self):
        half_a_cent = Invoice("INV-T", "ACCT-T", date(2026, 9, 1), (Line("Test", 1, 100),), 50)
        self.assertEqual(half_a_cent.tax_cents, 1)

    def test_tax_exempt_accounts_pay_no_tax(self):
        exempt = [i for i in self.invoices if i.account_id == "ACCT-1002"]
        self.assertEqual([i.tax_cents for i in exempt], [0, 0, 0])


if __name__ == "__main__":
    unittest.main()
